        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IArmorGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Enchantment, out var EnchantmentInfo))
            {
                yield return EnchantmentInfo;
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.PickUpSound, out var PickUpSoundInfo))
            {
                yield return PickUpSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.PutDownSound, out var PutDownSoundInfo))
            {
                yield return PutDownSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.EquipmentType, out var EquipmentTypeInfo))
            {
                yield return EquipmentTypeInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BlockBashImpactDataSet, out var BlockBashImpactDataSetInfo))
            {
                yield return BlockBashImpactDataSetInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AlternateBlockMaterial, out var AlternateBlockMaterialInfo))
            {
                yield return AlternateBlockMaterialInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Race, out var RaceInfo))
            {
                yield return RaceInfo;
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.InstanceNaming, out var InstanceNamingInfo))
            {
                yield return InstanceNamingInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BreakSound, out var BreakSoundInfo))
            {
                yield return BreakSoundInfo;
            }
            foreach (var item in obj.Armatures.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.ObjectTemplates is {} ObjectTemplatesItem)
            {
                foreach (var item in ObjectTemplatesItem.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.TemplateArmor, out var TemplateArmorInfo))
            {
                yield return TemplateArmorInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DamageCurve, out var DamageCurveInfo))
            {
                yield return DamageCurveInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MinDurabilityCurve, out var MinDurabilityCurveInfo))
            {
                yield return MinDurabilityCurveInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ConditionLossScale, out var ConditionLossScaleInfo))
            {
                yield return ConditionLossScaleInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BashConditionLossScale, out var BashConditionLossScaleInfo))
            {
                yield return BashConditionLossScaleInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AbsorbPercent, out var AbsorbPercentInfo))
            {
                yield return AbsorbPercentInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ValueCurrency, out var ValueCurrencyInfo))
            {
                yield return ValueCurrencyInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MO2S, out var MO2SInfo))
            {
                yield return MO2SInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MO4S, out var MO4SInfo))
            {
                yield return MO4SInfo;
            }
            yield break;
        }
        
        #region Duplicate
        public Armor Duplicate(
            IArmorGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Armor(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
